std::shared_ptr<int> target_ptr;
std::shared_ptr<int> source_ptr(new int(42));

// Simple atomic store (uses memory_order_seq_cst)
// Safely updates target_ptr's control block/use count
std::atomic_store(&target_ptr, source_ptr);

// Explicit memory ordering for high performance synchronization
std::atomic_store_explicit(
    &target_ptr,
    source_ptr,
    std::memory_order_release
);

// Note: atomic_store is essential for multithreaded assignments
// Target must be accessible to all threads writing/reading
std::shared_ptr<int> local_copy = target_ptr; // Non-atomic read
